import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { UserPlus, ArrowLeft, Mail, Lock, User } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { updateProfile } from 'firebase/auth';
import toast from 'react-hot-toast';

export default function Register() {
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    const navigate = useNavigate();
    const { register } = useAuth();

    const handleRegister = async (e) => {
        e.preventDefault();

        if (password !== confirmPassword) {
            return toast.error('Las contraseñas no coinciden.');
        }

        try {
            setIsLoading(true);
            const userCredential = await register(email, password);
            // Actualizar el perfil del usuario recién creado para que tenga su nombre
            await updateProfile(userCredential.user, {
                displayName: name
            });

            toast.success('¡Cuenta creada con éxito!');
            navigate('/'); // Redirigimos al home tras el registro
        } catch (error) {
            if (error.code === 'auth/email-already-in-use') {
                toast.error('El correo electrónico ya está registrado.');
            } else if (error.code === 'auth/weak-password') {
                toast.error('La contraseña debe tener al menos 6 caracteres.');
            } else {
                toast.error('Error al crear la cuenta.');
                console.error(error);
            }
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-black flex items-center justify-center relative overflow-hidden p-4">
            {/* Fondo Ambientado */}
            <div className="absolute inset-0 bg-[url('/banner.jpg')] bg-cover bg-center opacity-20 filter blur-sm"></div>
            <div className="absolute inset-0 bg-gradient-to-t from-black via-black/80 to-transparent"></div>

            <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.5 }}
                className="relative z-10 w-full max-w-md bg-[#111] border border-gray-800 p-8 rounded-sm shadow-[0_0_50px_rgba(234,88,12,0.1)]"
            >
                <div className="text-center mb-8">
                    <h2 className="text-3xl font-black italic text-white uppercase tracking-tighter mb-2">
                        Únete a <span className="text-orange-600">Thaiger</span>
                    </h2>
                    <p className="text-gray-400 text-sm">Crea tu cuenta y empieza tu transformación.</p>
                </div>

                <form className="space-y-5" onSubmit={handleRegister}>
                    {/* Nombre Completo */}
                    <div className="space-y-1">
                        <label className="text-xs uppercase font-bold text-gray-500 ml-1">Nombre Completo</label>
                        <div className="relative">
                            <User className="absolute left-4 top-3.5 text-gray-600 h-5 w-5" />
                            <input
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                placeholder="Tu Nombre"
                                className="w-full bg-[#0A0A0A] border border-gray-800 text-white px-12 py-3 rounded-sm focus:outline-none focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-all placeholder:text-gray-700"
                                required
                            />
                        </div>
                    </div>

                    {/* Email */}
                    <div className="space-y-1">
                        <label className="text-xs uppercase font-bold text-gray-500 ml-1">Correo Electrónico</label>
                        <div className="relative">
                            <Mail className="absolute left-4 top-3.5 text-gray-600 h-5 w-5" />
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                placeholder="usuario@ejemplo.com"
                                className="w-full bg-[#0A0A0A] border border-gray-800 text-white px-12 py-3 rounded-sm focus:outline-none focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-all placeholder:text-gray-700"
                                required
                            />
                        </div>
                    </div>

                    {/* Contraseña */}
                    <div className="space-y-1">
                        <label className="text-xs uppercase font-bold text-gray-500 ml-1">Contraseña</label>
                        <div className="relative">
                            <Lock className="absolute left-4 top-3.5 text-gray-600 h-5 w-5" />
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                placeholder="••••••••"
                                className="w-full bg-[#0A0A0A] border border-gray-800 text-white px-12 py-3 rounded-sm focus:outline-none focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-all placeholder:text-gray-700"
                                required
                            />
                        </div>
                    </div>

                    {/* Confirmar Contraseña */}
                    <div className="space-y-1">
                        <label className="text-xs uppercase font-bold text-gray-500 ml-1">Confirmar Contraseña</label>
                        <div className="relative">
                            <Lock className="absolute left-4 top-3.5 text-gray-600 h-5 w-5" />
                            <input
                                type="password"
                                value={confirmPassword}
                                onChange={(e) => setConfirmPassword(e.target.value)}
                                placeholder="••••••••"
                                className="w-full bg-[#0A0A0A] border border-gray-800 text-white px-12 py-3 rounded-sm focus:outline-none focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-all placeholder:text-gray-700"
                                required
                            />
                        </div>
                    </div>

                    <button type="submit" disabled={isLoading} className="w-full bg-orange-600 hover:bg-orange-700 disabled:opacity-50 text-white font-black uppercase italic tracking-wider py-4 rounded-sm transition-all transform hover:-translate-y-1 hover:shadow-lg flex items-center justify-center gap-2 mt-4">
                        <UserPlus size={20} /> {isLoading ? 'Creando cuenta...' : 'Crear Cuenta'}
                    </button>
                </form>

                <div className="mt-8 pt-6 border-t border-gray-800 text-center">
                    <p className="text-gray-500 text-sm mb-4">¿Ya tienes cuenta?</p>
                    <Link to="/login" className="text-orange-500 font-bold uppercase text-sm hover:text-white transition-colors flex items-center justify-center gap-2">
                        <ArrowLeft size={16} /> Volver al Login
                    </Link>
                </div>
            </motion.div>
        </div>
    );
}

import React, { useState, useMemo, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import Navbar from '../components/Navbar';
import ProductCard from '../components/ProductCard';
import { SlidersHorizontal, X } from 'lucide-react';

import { PRODUCTS, formatPrice } from '../data/products';

// Extraer categorías y marcas únicas del catálogo real
const uniqueCategories = [...new Set(PRODUCTS.map(p => p.category))].sort();
const uniqueBrands = [...new Set(PRODUCTS.map(p => p.brand))].sort();

// Lista de filtros dinámicos
const filterCategories = [
    { id: 'category', title: "Categorías", items: uniqueCategories },
    { id: 'brand', title: "Marcas", items: uniqueBrands },
    { id: 'price', title: "Precio", items: ["Hasta $500", "$500 - $1000", "+$1000"] },
];

export default function Shop() {
    const location = useLocation();
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    // Estado para guardar los filtros seleccionados
    const [selectedFilters, setSelectedFilters] = useState({
        category: [],
        brand: [],
        price: [],
        search: ''
    });
    const [sortBy, setSortBy] = useState('relevance');

    // Leer el estado de la navegación (por si venimos de hacer clic en una marca en el Home)
    useEffect(() => {
        if (location.state?.brand) {
            // eslint-disable-next-line
            setSelectedFilters(prev => ({
                ...prev,
                brand: [location.state.brand] // Establecemos la marca recibida como filtro activo
            }));

            // Limpiar el estado de la ubicación para que no se quede pegado si recargamos o navegamos
            window.history.replaceState({}, document.title);
        }

        if (location.state?.search) {
            setSelectedFilters(prev => ({
                ...prev,
                search: location.state.search
            }));
            window.history.replaceState({}, document.title);
        }
    }, [location.state]);

    // Manejar el cambio de un checkbox
    const handleFilterChange = (filterType, item) => {
        setSelectedFilters(prev => {
            const currentSelected = prev[filterType];
            if (currentSelected.includes(item)) {
                // Si ya está, lo quitamos
                return { ...prev, [filterType]: currentSelected.filter(i => i !== item) };
            } else {
                // Si no está, lo agregamos
                return { ...prev, [filterType]: [...currentSelected, item] };
            }
        });
    };

    // Filtrar los productos
    const filteredProducts = useMemo(() => {
        return PRODUCTS.filter(product => {
            // 1. Filtro por Categoría
            const categoryMatch = selectedFilters.category.length === 0 || selectedFilters.category.includes(product.category);

            // 2. Filtro por Marca
            const brandMatch = selectedFilters.brand.length === 0 || selectedFilters.brand.includes(product.brand);

            // 3. Filtro por Precio (usamos price1 como referencia pública)
            let priceMatch = selectedFilters.price.length === 0;
            if (selectedFilters.price.length > 0) {
                const p = product.price1;
                // Revisamos si el precio del producto cae en ALGUNO de los rangos seleccionados
                priceMatch = selectedFilters.price.some(range => {
                    if (range === "Hasta $500") return p <= 500;
                    if (range === "$500 - $1000") return p > 500 && p <= 1000;
                    if (range === "+$1000") return p > 1000;
                    return false;
                });
            }

            // 4. Filtro por Búsqueda (search)
            const searchLower = selectedFilters.search.toLowerCase();
            const searchMatch = !selectedFilters.search ||
                (product.name && product.name.toLowerCase().includes(searchLower)) ||
                (product.brand && product.brand.toLowerCase().includes(searchLower)) ||
                (product.category && product.category.toLowerCase().includes(searchLower));

            // Debe cumplir con TODOS los filtros activos
            return categoryMatch && brandMatch && priceMatch && searchMatch;
        });

        // Aplicamos Ordenamiento
        switch (sortBy) {
            case 'price_asc':
                result.sort((a, b) => a.price1 - b.price1);
                break;
            case 'price_desc':
                result.sort((a, b) => b.price1 - a.price1);
                break;
            case 'name_asc':
                result.sort((a, b) => (a.name || "").localeCompare(b.name || ""));
                break;
            case 'name_desc':
                result.sort((a, b) => (b.name || "").localeCompare(a.name || ""));
                break;
            default:
                break;
        }

        return result;
    }, [selectedFilters, sortBy]);

    return (
        <div className="bg-[#0A0A0A] min-h-screen text-white">
            <Navbar />

            <div className="container mx-auto pt-32 px-4 pb-12">
                <h1 className="text-4xl font-extrabold mb-8 uppercase text-center text-orange-500 tracking-wider">
                    Catálogo Completo
                </h1>

                <div className="flex flex-col lg:flex-row gap-8">

                    {/* Botón para abrir el sidebar en móvil */}
                    <button
                        className="lg:hidden bg-gray-800 text-white p-3 rounded-lg flex items-center justify-center gap-2 hover:bg-gray-700 transition-colors"
                        onClick={() => setIsSidebarOpen(true)}
                    >
                        <SlidersHorizontal className="h-5 w-5" /> Filtrar Productos
                    </button>

                    {/* === SIDEBAR DE FILTROS (Barra Lateral) === */}
                    <aside
                        className={`fixed lg:static top-0 left-0 h-full w-64 lg:w-72 bg-[#111] lg:bg-transparent shadow-2xl lg:shadow-none z-40 p-6 lg:p-0 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 overflow-y-auto`}
                    >
                        <div className="flex justify-between items-center mb-6 lg:hidden">
                            <h2 className="text-xl font-bold text-orange-500">Filtros</h2>
                            <button onClick={() => setIsSidebarOpen(false)} className="text-white hover:text-orange-500">
                                <X className="h-6 w-6" />
                            </button>
                        </div>

                        <div className="space-y-8">
                            {filterCategories.map((category) => (
                                <div key={category.id} className="border-b border-gray-800 pb-4">
                                    <h3 className="font-bold uppercase text-lg mb-3 tracking-wide">{category.title}</h3>
                                    <ul className="space-y-2">
                                        {category.items.map((item, i) => (
                                            <li key={i} className="flex items-center text-sm text-gray-400 hover:text-orange-500 cursor-pointer transition-colors">
                                                <input
                                                    type="checkbox"
                                                    id={`${category.id}-${item}`}
                                                    checked={selectedFilters[category.id].includes(item)}
                                                    onChange={() => handleFilterChange(category.id, item)}
                                                    className="h-4 w-4 text-orange-600 bg-gray-900 border-gray-700 rounded focus:ring-orange-500 mr-2"
                                                />
                                                <label htmlFor={`${category.id}-${item}`} className="cursor-pointer flex-1">{item}</label>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            ))}
                        </div>
                    </aside>

                    {/* === ÁREA PRINCIPAL DE PRODUCTOS === */}
                    <main className="flex-1">
                        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                            <p className="text-gray-500 text-sm">Mostrando {filteredProducts.length} resultados.</p>

                            <div className="flex items-center gap-4">
                                <select
                                    value={sortBy}
                                    onChange={(e) => setSortBy(e.target.value)}
                                    className="bg-gray-900 border border-gray-700 text-sm text-gray-300 rounded px-3 py-1.5 focus:outline-none focus:border-orange-500"
                                >
                                    <option value="relevance">Relevancia</option>
                                    <option value="price_asc">Precio: Menor a Mayor</option>
                                    <option value="price_desc">Precio: Mayor a Menor</option>
                                    <option value="name_asc">A - Z</option>
                                    <option value="name_desc">Z - A</option>
                                </select>

                                {/* Botón para limpiar filtros si hay alguno activo */}
                                {(selectedFilters.category.length > 0 || selectedFilters.brand.length > 0 || selectedFilters.price.length > 0 || selectedFilters.search) && (
                                    <button
                                        onClick={() => setSelectedFilters({ category: [], brand: [], price: [], search: '' })}
                                        className="text-orange-500 text-sm hover:text-orange-400 underline"
                                    >
                                        Limpiar todos los filtros
                                    </button>
                                )}
                            </div>
                        </div>

                        {filteredProducts.length === 0 ? (
                            <div className="text-center py-20 bg-[#111] rounded-xl border border-gray-800">
                                <h3 className="text-2xl font-bold text-gray-400 mb-2">No se encontraron productos</h3>
                                <p className="text-gray-500">Intenta cambiar los filtros seleccionados.</p>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-6">
                                {filteredProducts.map((product, index) => (
                                    <ProductCard
                                        key={product.id}
                                        id={product.id}
                                        delay={index % 4}
                                        brand={product.brand}
                                        details={product.name}
                                        price={formatPrice(product.price1)}
                                        category={product.category}
                                        image={product.image}
                                    />
                                ))}
                            </div>
                        )}
                    </main>
                </div>
            </div>

        </div>
    );
}
